import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { RATING_SCALE, notchChange, notchCalculator } from '../../src/ratings/notch.mjs';

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];

const INVALID = ['CC', 'D', 'NR', 'AAA+', 'Baa1', '', '   ', 'BBB +', null, undefined, 42, {}];

describe('RATING_SCALE (AC-1)', () => {
  test('has the 19 steps, best first', () => {
    assert.deepEqual(RATING_SCALE, EXPECTED_SCALE);
    assert.equal(RATING_SCALE.length, 19);
  });

  test('is immutable', () => {
    assert.equal(Object.isFrozen(RATING_SCALE), true);
    assert.throws(() => RATING_SCALE.push('CC'), TypeError);
    assert.throws(() => {
      RATING_SCALE[0] = 'X';
    }, TypeError);
    assert.equal(RATING_SCALE.length, 19);
    assert.equal(RATING_SCALE[0], 'AAA');
  });
});

describe('notchChange (AC-2, AC-3)', () => {
  const cases = [
    ['BBB+', 'BB+', 3],
    ['BBB+', 'BBB-', 2],
    ['A', 'A-', 1],
    ['AAA', 'CCC-', 18],
    ['BB', 'BBB', -3],
    ['CCC-', 'AAA', -18],
    ['BBB', 'BBB', 0],
  ];
  for (const [p, c, expected] of cases) {
    test(`${p} -> ${c} = ${expected}`, () => {
      const r = notchChange(p, c);
      assert.equal(r, expected);
      assert.equal(Number.isInteger(r), true);
    });
  }

  test('unchanged is +0, never -0', () => {
    assert.equal(Object.is(notchChange('BBB', 'BBB'), 0), true);
    assert.equal(Object.is(notchChange('AAA', 'AAA'), 0), true);
    assert.equal(Object.is(notchChange('CCC-', 'CCC-'), 0), true);
  });

  test('normalises whitespace and case', () => {
    assert.equal(notchChange(' bbb+ ', 'bb+'), 3);
    assert.equal(notchChange('\tAa-\n', 'a+'), 1);
  });
});

describe('notchCalculator', () => {
  test('lower-case input is normalised (AC-3)', () => {
    assert.deepEqual(notchCalculator('bbb+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
  });

  test('downgrade of 2 or more notches (AC-5)', () => {
    assert.deepEqual(notchCalculator('BBB+', 'BBB-'), { notches: 2, direction: 'downgrade', wl: 1 });
    assert.deepEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
    assert.deepEqual(notchCalculator('BB', 'B'), { notches: 3, direction: 'downgrade', wl: 2 });
    assert.deepEqual(notchCalculator('AAA', 'CCC-'), { notches: 18, direction: 'downgrade', wl: 2 });
  });

  test('1-notch downgrade gives WL 0 (AC-6)', () => {
    assert.deepEqual(notchCalculator('A', 'A-'), { notches: 1, direction: 'downgrade', wl: 0 });
    assert.deepEqual(notchCalculator('CCC', 'CCC-'), { notches: 1, direction: 'downgrade', wl: 0 });
  });

  test('upgrade gives negative notches and WL 0 (AC-7)', () => {
    assert.deepEqual(notchCalculator('BB', 'BBB'), { notches: -3, direction: 'upgrade', wl: 0 });
    assert.deepEqual(notchCalculator('BBB-', 'BBB+'), { notches: -2, direction: 'upgrade', wl: 0 });
    assert.deepEqual(notchCalculator('A-', 'A'), { notches: -1, direction: 'upgrade', wl: 0 });
    assert.deepEqual(notchCalculator('CCC-', 'AAA'), { notches: -18, direction: 'upgrade', wl: 0 });
  });

  test('unchanged gives +0 notches and WL 0 (AC-8)', () => {
    for (const [p, c] of [['BBB', 'BBB'], ['aaa', ' AAA ']]) {
      const r = notchCalculator(p, c);
      assert.deepEqual(r, { notches: 0, direction: 'unchanged', wl: 0 });
      assert.equal(Object.is(r.notches, 0), true);
    }
  });

  test('exhaustive over all 361 pairs (AC-9)', () => {
    let count = 0;
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        const r = notchCalculator(p, c);
        const n = notchChange(p, c);
        assert.deepEqual(Object.keys(r).sort(), ['direction', 'notches', 'wl']);
        assert.equal(r.notches, n);
        assert.equal(r.direction, n > 0 ? 'downgrade' : n < 0 ? 'upgrade' : 'unchanged');
        assert.equal(r.wl, n >= 3 ? 2 : n === 2 ? 1 : 0);
        count += 1;
      }
    }
    assert.equal(count, 361);
  });

  test('returns a new plain object on each call', () => {
    const a = notchCalculator('A', 'A-');
    const b = notchCalculator('A', 'A-');
    assert.notEqual(a, b);
    assert.equal(Object.getPrototypeOf(a), Object.prototype);
  });
});

describe('invalid input (AC-4, CON-errors)', () => {
  for (const [name, fn] of [['notchChange', notchChange], ['notchCalculator', notchCalculator]]) {
    for (const bad of INVALID) {
      const label = bad === undefined ? 'undefined' : JSON.stringify(bad);
      test(`${name}: ${label} as previous throws RangeError`, () => {
        assert.throws(() => fn(bad, 'BBB'), RangeError);
      });
      test(`${name}: ${label} as current throws RangeError`, () => {
        assert.throws(() => fn('BBB', bad), RangeError);
      });
    }
    test(`${name}: both arguments invalid throws RangeError`, () => {
      assert.throws(() => fn('XX', null), RangeError);
    });
  }

  test('non-string values never produce TypeError', () => {
    for (const bad of [new String('BBB'), [], true]) {
