  test('message names the argument and the offending value and lists valid ratings', () => {
    assert.throws(() => notchChange('XYZ', 'BBB'), (e) => {
      assert.ok(e instanceof RangeError);
      assert.match(e.message, /previous/);
      assert.match(e.message, /XYZ/);
      assert.match(e.message, /CCC-/);
      return true;
    });
    assert.throws(() => notchChange('BBB', 'XYZ'), /current/);
  });
});

describe('contract (AC-13)', () => {
  test('arity is exactly 2', () => {
    assert.equal(notchChange.length, 2);
    assert.equal(notchCalculator.length, 2);
  });

  test('source is pure: no imports, no I/O, no console', () => {
    const src = readFileSync(new URL('../../src/ratings/notch.mjs', import.meta.url), 'utf8');
    assert.doesNotMatch(src, /^\s*import\s/m);
    assert.doesNotMatch(src, /\bimport\s*\(/);
    assert.doesNotMatch(src, /require\(/);
    assert.doesNotMatch(src, /fetch/);
    assert.doesNotMatch(src, /process/);
    assert.doesNotMatch(src, /node:(fs|http|https)/);
    assert.doesNotMatch(src, /console\./);
  });

  test('inputs are not modified and nothing is written to stdout/stderr', () => {
    const p = ' bbb+ ';
    const c = 'bb+';
    const o = {};
    const origOut = process.stdout.write;
    const origErr = process.stderr.write;
    let written = 0;
    process.stdout.write = () => {
      written += 1;
      return true;
    };
    process.stderr.write = () => {
      written += 1;
      return true;
    };
    try {
      notchChange(p, c);
      notchCalculator(p, c);
      assert.throws(() => notchChange(o, 'BBB'), RangeError);
    } finally {
      process.stdout.write = origOut;
      process.stderr.write = origErr;
    }
    assert.equal(written, 0);
    assert.equal(p, ' bbb+ ');
    assert.equal(c, 'bb+');
    assert.equal(Object.keys(o).length, 0);
  });
});
EOF
