// Notch calculator (REQ-06-02). Pure functions, no I/O.
// Positive notches = downgrade, negative = upgrade, 0 = unchanged.

export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]);

function normalizeRating(value, argName) {
  const normalized = typeof value === 'string' ? value.trim().toUpperCase() : null;
  const index = normalized === null ? -1 : RATING_SCALE.indexOf(normalized);
  if (index === -1) {
    let shown;
    try {
      shown = typeof value === 'string' ? JSON.stringify(value) : String(value);
    } catch {
      shown = Object.prototype.toString.call(value);
    }
    throw new RangeError(
      `Invalid rating for ${argName}: ${shown}. Valid ratings: ${RATING_SCALE.join(', ')}`,
    );
  }
  return index;
}

export function notchChange(previous, current) {
  const from = normalizeRating(previous, 'previous');
  const to = normalizeRating(current, 'current');
  return to - from + 0; // "+ 0" turns -0 into +0
}

export function notchCalculator(previous, current) {
  const notches = notchChange(previous, current);
  const direction = notches > 0 ? 'downgrade' : notches < 0 ? 'upgrade' : 'unchanged';
  const wl = notches >= 3 ? 2 : notches === 2 ? 1 : 0;
  return { notches, direction, wl };
}
