// T-01 QA: integration tests for src/ratings/notch.mjs through its public exports.
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const MODULE_PATH = fileURLToPath(new URL('../../../src/ratings/notch.mjs', import.meta.url));
const MODULE_URL = pathToFileURL(MODULE_PATH).href;
const { RATING_SCALE, notchChange, notchCalculator } = await import(MODULE_URL);

const EXPECTED_SCALE = [
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
];

const INVALID = ['CC', 'D', 'NR', 'AAA+', 'Baa1', '', '   ', 'BBB +', null, undefined, 42, {}];
const label = (v) => (v === undefined ? 'undefined' : typeof v === 'object' && v !== null ? '{}' : JSON.stringify(v));

describe('AC-1: RATING_SCALE', () => {
  test('AC-1: RATING_SCALE deep-equals the 19 C1 ratings, best first', () => {
    assert.deepEqual([...RATING_SCALE], EXPECTED_SCALE);
    assert.equal(RATING_SCALE.length, 19);
    assert.ok(Array.isArray(RATING_SCALE));
  });

  test('AC-1 / X-scale-immutability: frozen, push and index write throw TypeError', () => {
    assert.equal(Object.isFrozen(RATING_SCALE), true);
    assert.throws(() => RATING_SCALE.push('CC'), TypeError);
    assert.throws(() => { RATING_SCALE[0] = 'X'; }, TypeError);
    assert.equal(RATING_SCALE.length, 19);
    assert.equal(RATING_SCALE[0], 'AAA');
  });
});

describe('AC-2: notchChange', () => {
  const cases = [
    ['BBB+', 'BB+', 3],
    ['BBB+', 'BBB-', 2],
    ['A', 'A-', 1],
    ['AAA', 'CCC-', 18],
    ['BB', 'BBB', -3],
    ['CCC-', 'AAA', -18],
    ['BBB', 'BBB', 0],
  ];
  for (const [p, c, expected] of cases) {
    test(`AC-2: notchChange(${p}, ${c}) is ${expected} (integer)`, () => {
      const r = notchChange(p, c);
      assert.equal(r, expected);
      assert.equal(typeof r, 'number');
      assert.equal(Number.isInteger(r), true);
    });
  }

  test('AC-2: unchanged is +0, never -0', () => {
    assert.equal(Object.is(notchChange('BBB', 'BBB'), 0), true);
    for (const r of RATING_SCALE) assert.equal(Object.is(notchChange(r, r), 0), true);
  });

  test('AC-2: result equals index(current) - index(previous) on RATING_SCALE for all pairs', () => {
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        assert.equal(notchChange(p, c), RATING_SCALE.indexOf(c) - RATING_SCALE.indexOf(p));
      }
    }
  });

  test('AC-2: extremes stay within [-18, 18]', () => {
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        const n = notchChange(p, c);
        assert.ok(n >= -18 && n <= 18);
      }
    }
  });
});

describe('AC-3: whitespace and case normalisation', () => {
  test('AC-3: notchChange(" bbb+ ", "bb+") is 3', () => {
    assert.equal(notchChange(' bbb+ ', 'bb+'), 3);
  });
  test('AC-3: notchChange("\\tAa-\\n", "a+") is 1', () => {
    assert.equal(notchChange('\tAa-\n', 'a+'), 1);
  });
  test('AC-3: notchCalculator("bbb+", "BB+") equals the canonical result', () => {
    assert.deepEqual(notchCalculator('bbb+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
    assert.deepEqual(notchCalculator('bbb+', 'BB+'), notchCalculator('BBB+', 'BB+'));
  });
  test('AC-3: every scale value is accepted padded and in lower case, with the same result', () => {
    for (const r of RATING_SCALE) {
      assert.equal(notchChange(`  ${r.toLowerCase()}\t`, r), 0);
      assert.equal(notchChange('AAA', ` \n${r.toLowerCase()} `), notchChange('AAA', r));
    }
  });
});

describe('AC-4: invalid input throws RangeError', () => {
  for (const bad of INVALID) {
    test(`AC-4: notchChange rejects ${label(bad)} as previous`, () => {
      assert.throws(() => notchChange(bad, 'BBB'), RangeError);
    });
    test(`AC-4: notchChange rejects ${label(bad)} as current`, () => {
      assert.throws(() => notchChange('BBB', bad), RangeError);
    });
    test(`AC-4: notchCalculator rejects ${label(bad)} as previous`, () => {
      assert.throws(() => notchCalculator(bad, 'BBB'), RangeError);
    });
    test(`AC-4: notchCalculator rejects ${label(bad)} as current`, () => {
      assert.throws(() => notchCalculator('BBB', bad), RangeError);
    });
  }

  test('AC-4: both arguments invalid throws RangeError', () => {
    assert.throws(() => notchChange('D', null), RangeError);
    assert.throws(() => notchCalculator(undefined, 'NR'), RangeError);
  });

  test('AC-4: other non-strings are rejected with RangeError, never TypeError', () => {
    for (const bad of [new String('BBB'), [], true]) {
      assert.throws(() => notchChange(bad, 'BBB'), RangeError);
      assert.throws(() => notchCalculator('BBB', bad), RangeError);
    }
  });

  test('AC-4: missing arguments throw RangeError', () => {
    assert.throws(() => notchChange(), RangeError);
    assert.throws(() => notchCalculator('BBB'), RangeError);
  });

  test('AC-4: the error is a plain RangeError whose message names argument and value', () => {
    let err;
    try { notchChange('CC', 'BBB'); } catch (e) { err = e; }
    assert.ok(err instanceof RangeError);
    assert.ok(!(err instanceof TypeError));
  });
});

describe('AC-5: downgrades of 2 or more notches', () => {
  const cases = [
    ['BBB+', 'BBB-', { notches: 2, direction: 'downgrade', wl: 1 }],
    ['BBB+', 'BB+', { notches: 3, direction: 'downgrade', wl: 2 }],
    ['BB', 'B', { notches: 3, direction: 'downgrade', wl: 2 }],
    ['AAA', 'CCC-', { notches: 18, direction: 'downgrade', wl: 2 }],
  ];
  for (const [p, c, expected] of cases) {
    test(`AC-5: notchCalculator(${p}, ${c}) -> ${JSON.stringify(expected)}`, () => {
      assert.deepEqual(notchCalculator(p, c), expected);
    });
  }
});

describe('AC-6: 1-notch downgrade gives WL 0', () => {
  for (const [p, c] of [['A', 'A-'], ['CCC', 'CCC-']]) {
    test(`AC-6: notchCalculator(${p}, ${c}) -> wl 0`, () => {
      assert.deepEqual(notchCalculator(p, c), { notches: 1, direction: 'downgrade', wl: 0 });
    });
  }
});

describe('AC-7: upgrades', () => {
  const cases = [
    ['BB', 'BBB', { notches: -3, direction: 'upgrade', wl: 0 }],
    ['BBB-', 'BBB+', { notches: -2, direction: 'upgrade', wl: 0 }],
    ['A-', 'A', { notches: -1, direction: 'upgrade', wl: 0 }],
    ['CCC-', 'AAA', { notches: -18, direction: 'upgrade', wl: 0 }],
  ];
  for (const [p, c, expected] of cases) {
    test(`AC-7: notchCalculator(${p}, ${c}) -> ${JSON.stringify(expected)}`, () => {
      assert.deepEqual(notchCalculator(p, c), expected);
    });
  }
});

describe('AC-8: unchanged rating', () => {
  for (const [p, c] of [['BBB', 'BBB'], ['aaa', ' AAA ']]) {
    test(`AC-8: notchCalculator(${JSON.stringify(p)}, ${JSON.stringify(c)}) is unchanged with +0`, () => {
      const r = notchCalculator(p, c);
      assert.deepEqual(r, { notches: 0, direction: 'unchanged', wl: 0 });
      assert.equal(Object.is(r.notches, 0), true);
    });
  }
});

describe('AC-9: all 361 scale pairs', () => {
  test('AC-9: notchCalculator is consistent with notchChange and the Ind. 13 thresholds for every pair', () => {
    let pairs = 0;
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        pairs++;
        const r = notchCalculator(p, c);
        const n = notchChange(p, c);
        const ctx = `${p} -> ${c}`;
        assert.deepEqual(Object.keys(r).sort(), ['direction', 'notches', 'wl'], ctx);
        assert.equal(r.notches, n, ctx);
        assert.equal(r.direction, n > 0 ? 'downgrade' : n < 0 ? 'upgrade' : 'unchanged', ctx);
        assert.equal(r.wl, n >= 3 ? 2 : n === 2 ? 1 : 0, ctx);
        if (n === 0) assert.equal(Object.is(r.notches, 0), true, ctx);
      }
    }
    assert.equal(pairs, 361);
  });

  test('AC-9: each call returns a new plain object', () => {
    const a = notchCalculator('BBB', 'BB');
    const b = notchCalculator('BBB', 'BB');
    assert.notEqual(a, b);
    assert.equal(Object.getPrototypeOf(a), Object.prototype);
    a.wl = 99;
    assert.equal(notchCalculator('BBB', 'BB').wl, 0);
  });
});

describe('AC-13 (notch part): contract and purity', () => {
  test('AC-13: notchChange.length and notchCalculator.length are 2', () => {
    assert.equal(notchChange.length, 2);
    assert.equal(notchCalculator.length, 2);
  });

  test('AC-13: source has no import, require, fetch, process, node:fs/http/https or console', () => {
    const raw = readFileSync(MODULE_PATH, 'utf8');
    const src = raw.replace(/\/\*[\s\S]*?\*\//g, '').replace(/^\s*\/\/.*$/gm, '');
    assert.doesNotMatch(src, /^\s*import\b/m);
    assert.doesNotMatch(src, /\bimport\s*\(/);
    assert.doesNotMatch(src, /\brequire\s*\(/);
    assert.doesNotMatch(src, /\bfetch\b/);
    assert.doesNotMatch(src, /\bprocess\b/);
    assert.doesNotMatch(src, /node:(fs|http|https)/);
    assert.doesNotMatch(src, /\bconsole\s*\./);
  });

  test('AC-13: arguments are not changed by the calls', () => {
    const p = ' bbb+ ';
    const c = 'bb+';
    const o = {};
    notchChange(p, c);
    notchCalculator(p, c);
    assert.throws(() => notchChange(o, 'BBB'), RangeError);
    assert.throws(() => notchCalculator('BBB', o), RangeError);
    assert.equal(p, ' bbb+ ');
    assert.equal(c, 'bb+');
    assert.equal(Object.keys(o).length, 0);
  });

  test('AC-13: calls write nothing to stdout or stderr (child process)', () => {
    const script = `
      const m = await import(${JSON.stringify(MODULE_URL)});
      const results = [];
      results.push(m.notchChange(' bbb+ ', 'bb+'));
      results.push(m.notchCalculator('BBB+', 'BB+'));
      results.push(m.notchCalculator('aaa', ' AAA '));
      for (const bad of ['CC', null, undefined, 42, {}]) {
        try { m.notchChange(bad, 'BBB'); } catch (e) { results.push(e instanceof RangeError); }
        try { m.notchCalculator('BBB', bad); } catch (e) { results.push(e instanceof RangeError); }
      }
      if (results.slice(3).some((x) => x !== true)) throw new Error('unexpected error type');
    `;
    const res = spawnSync(process.execPath, ['--input-type=module', '-e', script], { encoding: 'utf8' });
    assert.equal(res.status, 0, res.stderr);
    assert.equal(res.stdout, '');
    assert.equal(res.stderr, '');
  });

  test('AC-13: documented node -e probe returns the corrected 3-notch / WL 2 result', () => {
    const probe = `import(${JSON.stringify(MODULE_URL)}).then(m=>process.stdout.write(JSON.stringify(m.notchCalculator('BBB+','BB+'))))`;
    const res = spawnSync(process.execPath, ['-e', probe], { encoding: 'utf8' });
    assert.equal(res.status, 0, res.stderr);
    assert.deepEqual(JSON.parse(res.stdout), { notches: 3, direction: 'downgrade', wl: 2 });
  });
});
