import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { countryRatingChangeWl } from '../../src/indicators/countryRating.mjs';
import { notchChange, notchCalculator, RATING_SCALE } from '../../src/ratings/notch.mjs';

const MODULE_PATH = fileURLToPath(new URL('../../src/indicators/countryRating.mjs', import.meta.url));

describe('countryRatingChangeWl (Ind. 12)', () => {
  test('AC-10: downgrades map to 1 (1 notch) or 2 (2+ notches)', () => {
    const cases = [
      ['A', 'A-', 1],
      ['CCC', 'CCC-', 1],
      ['BBB+', 'BBB-', 2],
      ['BBB+', 'BB+', 2],
      ['AAA', 'CCC-', 2],
    ];
    for (const [p, c, expected] of cases) {
      const result = countryRatingChangeWl(p, c);
      assert.equal(typeof result, 'number');
      assert.equal(result, expected, `${p} -> ${c}`);
    }
  });

  test('AC-11: upgrades and unchanged ratings give 0', () => {
    for (const [p, c] of [['BB', 'BBB'], ['A-', 'A'], ['CCC-', 'AAA'], ['BBB', 'BBB']]) {
      assert.equal(countryRatingChangeWl(p, c), 0, `${p} -> ${c}`);
    }
  });

  test('AC-11: all 361 pairs follow the n >= 2 ? 2 : n === 1 ? 1 : 0 rule', () => {
    let count = 0;
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        const n = notchChange(p, c);
        const expected = n >= 2 ? 2 : n === 1 ? 1 : 0;
        assert.equal(countryRatingChangeWl(p, c), expected, `${p} -> ${c}`);
        count += 1;
      }
    }
    assert.equal(count, 361);
  });

  test('AC-12: thresholds differ deliberately from notchCalculator.wl', () => {
    const cases = [
      ['A', 'A-', 0, 1],
      ['BBB+', 'BBB-', 1, 2],
      ['BBB+', 'BB+', 2, 2],
    ];
    for (const [p, c, calcWl, indWl] of cases) {
      assert.equal(notchCalculator(p, c).wl, calcWl, `calculator ${p} -> ${c}`);
      assert.equal(countryRatingChangeWl(p, c), indWl, `indicator ${p} -> ${c}`);
    }
  });

  test('AC-3: trims whitespace and ignores letter case', () => {
    assert.equal(countryRatingChangeWl('  a ', 'a-'), 1);
  });

  test('AC-4: invalid input throws RangeError for previous and for current', () => {
    const invalid = ['CC', 'D', 'NR', 'AAA+', 'Baa1', '', '   ', 'BBB +', null, undefined, 42, {}];
    assert.equal(invalid.length, 12);
    for (const x of invalid) {
      assert.throws(() => countryRatingChangeWl(x, 'BBB'), RangeError, `previous = ${String(x)}`);
      assert.throws(() => countryRatingChangeWl('BBB', x), RangeError, `current = ${String(x)}`);
    }
  });

  test('AC-4: both arguments invalid throws RangeError', () => {
    assert.throws(() => countryRatingChangeWl('D', null), RangeError);
  });

  test('AC-4: the RangeError from notchChange reaches the caller unchanged', () => {
    let fromNotch;
    try {
      notchChange('CC', 'BBB');
    } catch (e) {
      fromNotch = e;
    }
    let fromWl;
    try {
      countryRatingChangeWl('CC', 'BBB');
    } catch (e) {
      fromWl = e;
    }
    assert.ok(fromWl instanceof RangeError);
    assert.equal(fromWl.constructor, RangeError);
    assert.equal(fromWl.message, fromNotch.message);
  });

  test('AC-13: source has one import (notchChange) and no I/O references', () => {
    const src = readFileSync(MODULE_PATH, 'utf8');
    const imports = src.match(/^\s*import\s[^;]*;?/gm) ?? [];
    assert.equal(imports.length, 1);
    assert.match(imports[0], /^\s*import \{ notchChange \} from '\.\.\/ratings\/notch\.mjs';?$/);
    assert.doesNotMatch(src, /require\(/);
    assert.doesNotMatch(src, /fetch/);
    assert.doesNotMatch(src, /process/);
    assert.doesNotMatch(src, /node:(fs|http|https)/);
    assert.doesNotMatch(src, /console\./);
  });

  test('AC-13: arity is exactly 2 (no override/options parameter)', () => {
    assert.equal(countryRatingChangeWl.length, 2);
  });

  test('AC-13: inputs are not mutated', () => {
    const p = '  a ';
    const c = 'a-';
    countryRatingChangeWl(p, c);
    assert.equal(p, '  a ');
    assert.equal(c, 'a-');

    const o = {};
    assert.throws(() => countryRatingChangeWl(o, 'BBB'), RangeError);
    assert.equal(Object.keys(o).length, 0);
  });

  test('result is always 0, 1 or 2 and never NaN', () => {
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        assert.ok([0, 1, 2].includes(countryRatingChangeWl(p, c)), `${p} -> ${c}`);
      }
    }
  });
});
