  });

  test('AC-13 / C8: calling the function writes nothing to stdout or stderr (child process)', () => {
    const script = `
      import { countryRatingChangeWl } from ${JSON.stringify(pathToFileURL(MODULE_PATH).href)};
      countryRatingChangeWl('A', 'A-');
